def Irreflexive (α : Type) (r : α → α → Prop) : Prop :=
  ∀ (a : α), ¬ (r a a)

def Transitive (α : Type) (r : α → α → Prop) : Prop :=
  ∀ (a b c : α), r a b → r b c → r a c

def IsStrictOrder (α : Type) (r : α → α → Prop) : Prop :=
  Irreflexive α r ∧ Transitive α r

def Antisymmetric (α : Type) (r : α → α → Prop) : Prop :=
  ∀ (a b : α), r a b → r b a → a = b

def Irreflexive (α : Type) (r : α → α → Prop) : Prop :=
  ∀ (a : α), ¬ (r a a)

def Function.LeftInverse (α β : Type) (g : β → α) (f : α → β) : Prop :=
  ∀ (x : α), g (f x) = x

def Function.RightInverse (α β : Type) (g : β → α) (f : α → β) : Prop :=
  ∀ (y : β), f (g y) = y

def Function.Inverse (α β : Type) (f : α → β) (g : β → α) : Prop :=
  LeftInverse α β g f ∧ RightInverse α β g f

def Set.InjOn (α β : Type) (f : α → β) (A : Set α) : Prop :=
  ∀ (x : α), x ∈ A → ∀ (y : α), y ∈ A → f x = f y → x = y

def Set.Le (α β : Type) (A : Set α) (B : Set β) : Prop :=
  ∃ (f : α → β), Set.InjOn α β f A ∧ Set.MapsTo α β f A B

def CH : Prop :=
  ∀ (X : Set (Set Nat)), (@Set.univ Nat) ≼ X →
    (@Set.univ Nat) ≈ X ∨ X ≈ (𝒫 (@Set.univ Nat))

def Set.sUnion (α : Type) (F : Set (Set α)) : Set α :=
  fun (x : α) => ∃ (A : Set α), A ∈ F ∧ x ∈ A

def Set.sInter (α : Type) (F : Set (Set α)) : Set α :=
  fun (x : α) => ∀ (A : Set α), A ∈ F → x ∈ A

def intRel (a b : Prod Nat Nat) : Prop :=
  Nat.add (Prod.fst Nat Nat a) (Prod.snd Nat Nat b) =
  Nat.add (Prod.fst Nat Nat b) (Prod.snd Nat Nat a)

def Int : Type := @Quot.{1} (Prod Nat Nat) intRel

def intOfNat (n : Nat) : Int :=
  @Quot.mk.{1} (Prod Nat Nat) intRel (@prod_mk Nat Nat n Nat.zero)

theorem demo_quot_lift_iota (α β : Type) (r : α → α → Prop) (f : α → β)
    (h : ∀ (a b : α), r a b → f a = f b) (a : α) :
    @Quot.lift.{1, 1} α r β f h (@Quot.mk.{1} α r a) = f a :=
  @Eq.refl.{1} β (f a)

def addRep (a b : Prod Nat Nat) : Prod Nat Nat :=
  @prod_mk Nat Nat
    (Nat.add (Prod.fst Nat Nat a) (Prod.fst Nat Nat b))
    (Nat.add (Prod.snd Nat Nat a) (Prod.snd Nat Nat b))

def negRep (p : Prod Nat Nat) : Prod Nat Nat :=
  @prod_mk Nat Nat (Prod.snd Nat Nat p) (Prod.fst Nat Nat p)

def subRep (a b : Prod Nat Nat) : Prod Nat Nat :=
  addRep a (negRep b)

def Cardinal : Type 1 :=
  @Quot.{2} ((Type)) (fun (x : Type) (y : Type) => Type.Equiv x y)

def Cardinal.mk (α : Type) : Cardinal :=
  @Quot.mk.{2} ((Type)) (fun (x : Type) (y : Type) => Type.Equiv x y) α

def LeOn (α : Type) (β : Type) (A : Set α) (B : Set β) : Prop :=
  ∃ (f : α → β), Set.InjOn α β f A ∧ Set.MapsTo α β f A B

theorem leOn_of_subset (α : Type) (A : Set α) (B : Set α) (h : A ⊆ B) : LeOn α α A B
